using System.Text;using AssetForge.Core.Models;using AssetForge.Infrastructure.Data;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using QRCoder;namespace AssetForge.Web.Pages;public class LabelsModel(AssetForgeDbContext db):PageModel{public List<Asset> Assets{get;set;}=[];public async Task OnGetAsync()=>Assets=await db.Assets.Include(x=>x.Category).OrderBy(x=>x.AssetTag).ToListAsync();public IActionResult OnGetQr(string tag,bool download=false){var url=$"{Request.Scheme}://{Request.Host}/Lookup/{Uri.EscapeDataString(tag)}";using var data=QRCodeGenerator.GenerateQrCode(url,QRCodeGenerator.ECCLevel.Q);var svg=new SvgQRCode(data).GetGraphic(5,"#08110f","#ffffff",true);return File(Encoding.UTF8.GetBytes(svg),"image/svg+xml",download?$"{tag}-qr.svg":null);}}
